class _CompatDiffer:
    """Symmetric diff of two validated snapshots, aligned with ``check``."""

    def __init__(self) -> None:
        self.changes: list[dict] = []
        self.reasons: set[str] = set()
        # One deterministic witness recipe per breaking pair position. Each
        # recipe is the step stack from the root object to that position; it
        # lets a record be built straight from a schema tree without either
        # matching change strings or re-deriving the structural alignment.
        self.recipes: list[tuple[str, tuple[str, ...]]] = []
        self._steps: list[str] = []

    @contextlib.contextmanager
    def _step(self, step: str) -> Iterator[None]:
        self._steps.append(step)
        try:
            yield
        finally:
            self._steps.pop()

    def witness(
        self, direction: str, kind: str, *, force: bool = False
    ) -> None:
        """Record a witness recipe for one breaking pair position.

        ``direction`` names the accepting (record) side for the breaking
        direction being witnessed; ``kind`` is the leaf kind the record
        must force at that position. A present-value witness (``force``
        false) only applies when the accepting side actually carries the
        kind, which the caller has already established; a forced witness
        drives a value the rejecting side cannot accept.
        """
        self.recipes.append((direction, tuple(self._steps) + (kind,)))

    def diff(self, old_root: dict, new_root: dict) -> dict:
        backward, forward = self.compare_object(old_root, new_root, "$")
        self.changes.sort(key=lambda change: (change["path"], change["change"]))
        return {
            "backward": backward,
            "forward": forward,
            "changes": self.changes,
            "unknown_reasons": sorted(self.reasons),
        }

    def change(self, path: str, category: str, breaking: bool) -> None:
        self.changes.append(
            {"path": path, "change": category, "breaking": False}
            if not breaking
            else {"path": path, "change": category, "breaking": True}
        )

