def _compat_report(
    old_revision: int, new_revision: int, old_root: dict, new_root: dict
) -> dict:
    report = _CompatDiffer().diff(old_root, new_root)
    return {"from": old_revision, "to": new_revision, **report}


def _normalize_overflow_names(node: Any) -> None:
